const ADVENTURE_BY_ID = Object.fromEntries(ADVENTURES.map(a => [a.id, a]));

// The adventure this game is playing. Old saves from before the picker are Everlight.
function adventureFor(game) {
  return ADVENTURE_BY_ID[game && game.adventureId] || ADVENTURES[0];
}
